// The fixture's own source. Every specifier here is a string in a JSON file, which is
// how this repository keeps a third-party import out of its own dependency proof.
import { readFileSync } from 'node:fs';
import chalk from 'chalk';
import minimist from 'minimist';
import semver from 'semver';
import express from 'express';

const name = 'se' + 'mver';
const late = await import(name);

export function main(argv) {
  const args = minimist(argv);
  const ok = semver.valid(args.v ?? '1.0.0') !== null;
  readFileSync('package.json', 'utf8');
  express();
  return chalk.green(ok ? 'yes' : 'no') + late.SEMVER_SPEC;
}

